CREATE OR REPLACE FUNCTION public.bank_borrow(p_amount double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_amount double precision := floor(coalesce(p_amount, 0));
  v_acct public.bank_accounts%rowtype;
  v_limit double precision;
  v_available double precision;
begin
  if v_uid is null then raise exception 'unauthenticated'; end if;
  if v_amount <= 0 then raise exception 'bank_invalid_amount'; end if;
  perform public.bank_touch(v_uid);

  select * into v_acct from public.bank_accounts where player_id = v_uid for update;
  if v_acct.borrow_frozen_until is not null and now() < v_acct.borrow_frozen_until then
    raise exception 'bank_borrow_frozen';
  end if;
  if (v_acct.loan_principal + v_acct.loan_interest_accrued) > 0
     and v_acct.loan_due_at is not null and now() > v_acct.loan_due_at then
    raise exception 'bank_in_default';
  end if;
  v_limit := public.bank_borrow_limit(v_acct.credit_score, v_acct.balance);
  v_available := v_limit - (v_acct.loan_principal + v_acct.loan_interest_accrued);
  if v_amount > v_available then raise exception 'bank_over_limit'; end if;

  update public.bank_accounts
     set loan_principal = loan_principal + v_amount,
         loan_due_at = case when loan_principal <= 0 then now() + interval '7 days' else loan_due_at end,
         loan_opened_at = case when loan_principal <= 0 then now() else loan_opened_at end,
         updated_at = now()
   where player_id = v_uid
   returning * into v_acct;

  update public.players set money = money + v_amount where id = v_uid;

  insert into public.bank_transactions (player_id, kind, amount, balance_after, loan_after, credit_after, memo)
  values (v_uid, 'borrow', v_amount, v_acct.balance,
          v_acct.loan_principal + v_acct.loan_interest_accrued, v_acct.credit_score, 'Loan drawn');
  return public.bank_dashboard_json(v_uid);
end;
$function$

CREATE OR REPLACE FUNCTION public.bank_deposit(p_amount double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_amount double precision := floor(coalesce(p_amount, 0));
  v_money double precision;
  v_acct public.bank_accounts%rowtype;
begin
  if v_uid is null then raise exception 'unauthenticated'; end if;
  if v_amount <= 0 then raise exception 'bank_invalid_amount'; end if;
  perform public.bank_touch(v_uid);

  update public.players set money = money - v_amount
   where id = v_uid and money >= v_amount
   returning money into v_money;
  if v_money is null then raise exception 'bank_insufficient_wallet'; end if;

  update public.bank_accounts
     set balance = balance + v_amount,
         updated_at = now()
   where player_id = v_uid
   returning * into v_acct;

  insert into public.bank_transactions (player_id, kind, amount, balance_after, loan_after, credit_after, memo)
  values (v_uid, 'deposit', v_amount, v_acct.balance,
          v_acct.loan_principal + v_acct.loan_interest_accrued, v_acct.credit_score, 'Deposit to savings');
  return public.bank_dashboard_json(v_uid);
end;
$function$

CREATE OR REPLACE FUNCTION public.bank_repay(p_amount double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_amount double precision := floor(coalesce(p_amount, 0));
  v_acct public.bank_accounts%rowtype;
  v_owed double precision;
  v_pay double precision;
  v_money double precision;
  v_to_interest double precision;
  v_to_principal double precision;
  v_on_time boolean;
  v_credit_gain integer;
  v_cleared boolean;
  v_held interval;
begin
  if v_uid is null then raise exception 'unauthenticated'; end if;
  if v_amount <= 0 then raise exception 'bank_invalid_amount'; end if;
  perform public.bank_touch(v_uid);

  select * into v_acct from public.bank_accounts where player_id = v_uid for update;
  v_owed := v_acct.loan_principal + v_acct.loan_interest_accrued;
  if v_owed <= 0 then raise exception 'bank_no_loan'; end if;

  v_pay := least(v_amount, v_owed);
  update public.players set money = money - v_pay
   where id = v_uid and money >= v_pay
   returning money into v_money;
  if v_money is null then raise exception 'bank_insufficient_wallet'; end if;

  v_to_interest := least(v_pay, v_acct.loan_interest_accrued);
  v_to_principal := v_pay - v_to_interest;
  v_cleared := (v_acct.loan_principal - v_to_principal) <= 0.0001
               and (v_acct.loan_interest_accrued - v_to_interest) <= 0.0001;
  v_on_time := v_acct.loan_due_at is null or now() <= v_acct.loan_due_at;
  v_held := now() - coalesce(v_acct.loan_opened_at, now());

  if v_cleared
     and v_acct.loan_principal >= 50000
     and v_held >= interval '24 hours' then
    v_credit_gain := case when v_on_time then 15 else 8 end;
  else
    v_credit_gain := 0;
  end if;

  update public.bank_accounts
     set loan_interest_accrued = greatest(0, loan_interest_accrued - v_to_interest),
         loan_principal = greatest(0, loan_principal - v_to_principal),
         credit_score = least(850, credit_score + v_credit_gain),
         on_time_repayments = on_time_repayments + case when v_credit_gain > 0 and v_on_time then 1 else 0 end,
         loan_due_at = case when v_cleared then null else loan_due_at end,
         loan_opened_at = case when v_cleared then null else loan_opened_at end,
         updated_at = now()
   where player_id = v_uid
   returning * into v_acct;

  insert into public.bank_transactions (player_id, kind, amount, balance_after, loan_after, credit_after, memo)
  values (v_uid, 'repay', v_pay, v_acct.balance,
          v_acct.loan_principal + v_acct.loan_interest_accrued, v_acct.credit_score,
          case when v_cleared then 'Loan repaid in full' else 'Loan repayment' end);
  return public.bank_dashboard_json(v_uid);
end;
$function$

CREATE OR REPLACE FUNCTION public.bank_touch(p_uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_acct public.bank_accounts%rowtype;
  v_days numeric;
  v_interest double precision;
  v_loan_interest double precision;
  v_late_fee double precision;
  v_owed double precision;
  v_seize double precision;
  v_seize_interest double precision;
  v_seize_principal double precision;
  v_savings_daily_rate constant numeric := power(1.065::numeric, 1::numeric / 365) - 1;
begin
  insert into public.bank_accounts (player_id)
  values (p_uid)
  on conflict (player_id) do nothing;

  select * into v_acct from public.bank_accounts where player_id = p_uid for update;

  -- Savings interest: 6.5% effective annual yield, compounded daily.
  v_days := greatest(0, extract(epoch from (now() - v_acct.last_interest_at)) / 86400.0);
  if v_acct.balance > 0 and v_days > 0 then
    v_interest := v_acct.balance * (power(1 + v_savings_daily_rate, v_days) - 1);
    if v_interest >= 0.005 then
      update public.bank_accounts
         set balance = balance + v_interest,
             last_interest_at = now(),
             updated_at = now()
       where player_id = p_uid;
      insert into public.bank_transactions (player_id, kind, amount, balance_after, loan_after, credit_after, memo)
      values (p_uid, 'interest', v_interest, v_acct.balance + v_interest,
              v_acct.loan_principal + v_acct.loan_interest_accrued, v_acct.credit_score, 'Savings interest');
      select * into v_acct from public.bank_accounts where player_id = p_uid for update;
    else
      update public.bank_accounts set last_interest_at = now() where player_id = p_uid;
    end if;
  else
    update public.bank_accounts set last_interest_at = now() where player_id = p_uid;
  end if;

  -- Loan interest: compound the credit-scaled daily rate on the principal.
  v_days := greatest(0, extract(epoch from (now() - v_acct.last_loan_accrual_at)) / 86400.0);
  if v_acct.loan_principal > 0 and v_days > 0 then
    v_loan_interest := v_acct.loan_principal * (power(1 + public.bank_loan_daily_rate(v_acct.credit_score), v_days) - 1);
    if v_loan_interest >= 0.005 then
      update public.bank_accounts
         set loan_interest_accrued = loan_interest_accrued + v_loan_interest,
             last_loan_accrual_at = now(),
             updated_at = now()
       where player_id = p_uid;
      insert into public.bank_transactions (player_id, kind, amount, balance_after, loan_after, credit_after, memo)
      values (p_uid, 'loan_interest', v_loan_interest, v_acct.balance,
              v_acct.loan_principal + v_acct.loan_interest_accrued + v_loan_interest, v_acct.credit_score, 'Loan interest');
      select * into v_acct from public.bank_accounts where player_id = p_uid for update;
    else
      update public.bank_accounts set last_loan_accrual_at = now() where player_id = p_uid;
    end if;
  else
    update public.bank_accounts set last_loan_accrual_at = now() where player_id = p_uid;
  end if;

  -- Default handling. Read fresh values first (interest may have moved them).
  select * into v_acct from public.bank_accounts where player_id = p_uid for update;
  if (v_acct.loan_principal + v_acct.loan_interest_accrued) > 0
     and v_acct.loan_due_at is not null
     and now() > v_acct.loan_due_at then

    -- (1) Right of offset: seize savings to service the defaulted loan,
    -- interest first then principal, capped at what is owed.
    v_owed := v_acct.loan_principal + v_acct.loan_interest_accrued;
    v_seize := least(v_acct.balance, v_owed);
    if v_seize > 0 then
      v_seize_interest := least(v_seize, v_acct.loan_interest_accrued);
      v_seize_principal := v_seize - v_seize_interest;
      update public.bank_accounts
         set balance = balance - v_seize,
             loan_interest_accrued = greatest(0, loan_interest_accrued - v_seize_interest),
             loan_principal = greatest(0, loan_principal - v_seize_principal),
             updated_at = now()
       where player_id = p_uid
       returning * into v_acct;
      insert into public.bank_transactions (player_id, kind, amount, balance_after, loan_after, credit_after, memo)
      values (p_uid, 'seizure', v_seize, v_acct.balance,
              v_acct.loan_principal + v_acct.loan_interest_accrued, v_acct.credit_score,
              'Savings seized to cover overdue loan');
    end if;

    v_owed := v_acct.loan_principal + v_acct.loan_interest_accrued;
    if v_owed <= 0.0001 then
      -- Offset cleared the debt outright; the loan is settled.
      update public.bank_accounts set loan_due_at = null, updated_at = now()
       where player_id = p_uid;
    else
      -- (2) Still in default: one 2% late fee + credit hit, push the due date.
      v_late_fee := v_acct.loan_principal * 0.02;
      update public.bank_accounts
         set loan_interest_accrued = loan_interest_accrued + v_late_fee,
             credit_score = greatest(300, credit_score - 40),
             missed_marks = missed_marks + 1,
             loan_due_at = now() + interval '3 days',
             updated_at = now()
       where player_id = p_uid;
      insert into public.bank_transactions (player_id, kind, amount, balance_after, loan_after, credit_after, memo)
      values (p_uid, 'penalty', v_late_fee, v_acct.balance,
              v_acct.loan_principal + v_acct.loan_interest_accrued + v_late_fee,
              greatest(300, v_acct.credit_score - 40), 'Missed payment: 2% late fee and credit penalty');
    end if;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.bank_withdraw(p_amount double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_amount double precision := floor(coalesce(p_amount, 0));
  v_acct public.bank_accounts%rowtype;
begin
  if v_uid is null then raise exception 'unauthenticated'; end if;
  if v_amount <= 0 then raise exception 'bank_invalid_amount'; end if;
  perform public.bank_touch(v_uid);

  update public.bank_accounts
     set balance = balance - v_amount,
         updated_at = now()
   where player_id = v_uid and balance >= v_amount
   returning * into v_acct;
  if v_acct.player_id is null then raise exception 'bank_insufficient_balance'; end if;

  update public.players set money = money + v_amount where id = v_uid;

  insert into public.bank_transactions (player_id, kind, amount, balance_after, loan_after, credit_after, memo)
  values (v_uid, 'withdraw', v_amount, v_acct.balance,
          v_acct.loan_principal + v_acct.loan_interest_accrued, v_acct.credit_score, 'Withdraw from savings');
  return public.bank_dashboard_json(v_uid);
end;
$function$

CREATE OR REPLACE FUNCTION public.buy_shares(p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_money numeric; v_fee numeric := 0.01; v_shares numeric; v_i numeric; v_eff numeric;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not public.share_market_is_open() then raise exception 'market_closed'; end if;
  if p_amount is null or p_amount <= 0 or p_amount > 1e15 then raise exception 'invalid_amount'; end if;
  select money into v_money from public.players where id = v_uid for update;
  if v_money is null then raise exception 'player_not_found'; end if;
  if p_amount > v_money then raise exception 'insufficient_funds'; end if;
  -- Fill at the midpoint of this buy's own price impact (pre + post)/2.
  v_i := coalesce((select sum(total_invested) from public.player_shares), 0);
  v_eff := (public.share_price_at(v_i) + public.share_price_at(v_i + p_amount)) / 2.0;
  v_shares := p_amount / (v_eff * (1 + v_fee));
  update public.players set money = money - p_amount where id = v_uid;
  insert into public.player_shares (player_id, shares, total_invested, updated_at)
    values (v_uid, v_shares, p_amount, now())
  on conflict (player_id) do update
    set shares = player_shares.shares + excluded.shares,
        total_invested = player_shares.total_invested + excluded.total_invested,
        updated_at = now();
  return public.get_share_market();
end $function$

CREATE OR REPLACE FUNCTION public.guild_purchase_points_with_cash(p_player_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_member public.guild_members%rowtype;
  v_guild public.guilds%rowtype;
  v_date date := (now() at time zone 'utc')::date;
  v_purchase_number integer;
  v_costs bigint[] := array[1000000,1500000,2000000,3000000,5000000];
  v_cost bigint;
  v_money numeric;
  v_reset_at timestamptz := ((v_date + 1)::timestamp at time zone 'UTC');
begin
  select * into v_member
  from public.guild_members
  where player_id = p_player_id;
  if not found then raise exception 'not_in_guild'; end if;

  -- Every member may contribute personal cash to the shared treasury.
  select * into v_guild from public.guilds where id = v_member.guild_id for update;
  if not found then raise exception 'guild_not_found'; end if;

  select count(*)::integer + 1 into v_purchase_number
  from public.guild_point_cash_contributions
  where guild_id = v_member.guild_id and contribution_date = v_date;
  if v_purchase_number > 5 then raise exception 'guild_point_purchase_limit'; end if;
  v_cost := v_costs[v_purchase_number];

  select money into v_money from public.players where id = p_player_id for update;
  if not found then raise exception 'player_not_found'; end if;
  if coalesce(v_money, 0) < v_cost then raise exception 'insufficient_money'; end if;

  update public.players set money = money - v_cost where id = p_player_id returning money into v_money;
  update public.guilds set guild_points = guild_points + 100, updated_at = now()
  where id = v_member.guild_id returning * into v_guild;

  insert into public.guild_point_cash_contributions(
    guild_id, player_id, contribution_date, purchase_number, money_spent, points_awarded
  ) values(v_member.guild_id, p_player_id, v_date, v_purchase_number, v_cost, 100);

  insert into public.guild_activity(guild_id, actor_id, action, details)
  values(v_member.guild_id, p_player_id, 'guild_points_funded',
    jsonb_build_object('money', v_cost, 'points', 100, 'purchaseNumber', v_purchase_number));

  return jsonb_build_object(
    'ok', true,
    'moneySpent', v_cost,
    'playerMoney', v_money,
    'pointsAwarded', 100,
    'guildPoints', v_guild.guild_points,
    'purchaseCount', v_purchase_number,
    'remainingPurchases', 5 - v_purchase_number,
    'nextCost', case when v_purchase_number < 5 then v_costs[v_purchase_number + 1] else null end,
    'resetsAt', v_reset_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.museum_expand(p_player_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_capacity integer; v_cost numeric; v_money numeric;
begin
  insert into public.museum_profiles(player_id) values(p_player_id) on conflict do nothing;
  select capacity into v_capacity from public.museum_profiles where player_id=p_player_id for update;
  if v_capacity >= 10 then raise exception 'museum_capacity_maxed'; end if;
  v_cost := case v_capacity+1 when 5 then 2000000 when 6 then 5000000 when 7 then 10000000 when 8 then 20000000 when 9 then 40000000 else 75000000 end;
  select money into v_money from public.players where id=p_player_id for update;
  if coalesce(v_money,0) < v_cost then raise exception 'not_enough_money'; end if;
  update public.players set money=money-v_cost where id=p_player_id;
  update public.museum_profiles set capacity=capacity+1,updated_at=now() where player_id=p_player_id;
  insert into public.museum_purchases(player_id,purchase_kind,money_removed,details)
  values(p_player_id,'capacity',v_cost,jsonb_build_object('slot',v_capacity+1));
  return jsonb_build_object('capacity',v_capacity+1,'cost',v_cost);
end $function$

CREATE OR REPLACE FUNCTION public.sell_inventory_gem(p_player_id uuid, p_specimen_id bigint)
 RETURNS double precision
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_value double precision; v_locked boolean; v_new_money double precision; v_gem_name text; v_name text;
begin
  select value,locked,gem_name into v_value,v_locked,v_gem_name from public.inventory_gems
    where id=p_specimen_id and player_id=p_player_id for update;
  if not found then raise exception 'gem_not_found'; end if;
  if v_locked then raise exception 'gem_locked'; end if;
  if public.player_has_mine_artifact(p_player_id,'foreman-seal') then v_value:=v_value*1.03; end if;
  update public.players set money=money+v_value,lifetime_earnings=lifetime_earnings+v_value
    where id=p_player_id returning money into v_new_money;
  delete from public.inventory_gems where id=p_specimen_id and player_id=p_player_id;
  begin select username into v_name from public.players where id=p_player_id;
    insert into public.global_cash_events(player_name,gem_name,amount) values(v_name,v_gem_name,v_value);
  exception when others then null; end;
  return v_new_money;
end $function$

CREATE OR REPLACE FUNCTION public.sell_shares(p_shares numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_fee numeric := 0.01;
  v_have numeric; v_invested numeric; v_sell numeric; v_proceeds numeric; v_basis_out numeric; v_i numeric; v_eff numeric;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not public.share_market_is_open() then raise exception 'market_closed'; end if;
  if p_shares is null or p_shares <= 0 then raise exception 'invalid_amount'; end if;
  select shares, total_invested into v_have, v_invested
    from public.player_shares where player_id = v_uid for update;
  if v_have is null or v_have <= 0 then raise exception 'no_shares'; end if;
  v_sell := least(p_shares, v_have);
  v_basis_out := case when v_have > 0 then v_invested * (v_sell / v_have) else 0 end;
  -- Fill at the midpoint of this sell's own price impact — dumping a big block
  -- crashes your own average fill, so it can't extract the pump.
  v_i := coalesce((select sum(total_invested) from public.player_shares), 0);
  v_eff := (public.share_price_at(v_i) + public.share_price_at(greatest(0, v_i - v_basis_out))) / 2.0;
  v_proceeds := v_sell * v_eff * (1 - v_fee);
  update public.player_shares
    set shares = shares - v_sell,
        total_invested = greatest(0, total_invested - v_basis_out),
        updated_at = now()
    where player_id = v_uid;
  update public.players set money = money + v_proceeds where id = v_uid;
  return public.get_share_market();
end $function$

CREATE OR REPLACE FUNCTION public.war_resolve_due()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_w public.player_wars%rowtype; v_cs numeric; v_os numeric; v_winner uuid; v_net numeric; v_rake numeric; v_n integer := 0;
begin
  -- Expire never-answered challenges and refund the challenger's ante.
  for v_w in select * from public.player_wars where status='pending' and created_at < now() - interval '48 hours' for update loop
    if v_w.stake > 0 then update public.players set money = money + v_w.stake where id = v_w.challenger_id; end if;
    update public.player_wars set status='expired', resolved_at=now(), pot=0 where id = v_w.id;
  end loop;

  for v_w in select * from public.player_wars where status='active' and ends_at <= now() for update loop
    v_cs := greatest(0, public.war_metric_value(v_w.challenger_id, v_w.metric) - coalesce(v_w.challenger_start,0));
    v_os := greatest(0, public.war_metric_value(v_w.opponent_id,   v_w.metric) - coalesce(v_w.opponent_start,0));
    if v_cs > v_os then v_winner := v_w.challenger_id;
    elsif v_os > v_cs then v_winner := v_w.opponent_id;
    else v_winner := null; end if;  -- tie

    if v_winner is null then
      -- Tie: refund each ante.
      if v_w.stake > 0 then
        update public.players set money = money + v_w.stake where id = v_w.challenger_id;
        update public.players set money = money + v_w.stake where id = v_w.opponent_id;
      end if;
    elsif v_w.pot > 0 then
      -- Wagered: winner takes pot minus 5% rake (burned = economy sink).
      v_rake := round(v_w.pot * 0.05);
      v_net := v_w.pot - v_rake;
      update public.players set money = money + v_net where id = v_winner;
      update public.players set lifetime_money_burned = coalesce(lifetime_money_burned,0) + v_rake where id = v_winner;
    else
      -- Friendly: the game hands the winner a modest prize.
      perform public.apply_reward_object(v_winner, '{"type":"money","amount":200000}'::jsonb);
      perform public.apply_reward_object(v_winner, '{"type":"potion","consumableId":"lucky-potion-1","amount":1}'::jsonb);
    end if;

    update public.player_wars set status='finished', winner_id=v_winner,
      challenger_score=v_cs, opponent_score=v_os, resolved_at=now() where id = v_w.id;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $function$
